<?php require_once "../db.php";require_role("Teacher");$id=(int)($_GET["id"]??0);$st=$conn->prepare("SELECT * FROM questions WHERE id=?");$st->bind_param("i",$id);$st->execute();$q=$st->get_result()->fetch_assoc();if(!$q)die("Question not found.");if($_SERVER["REQUEST_METHOD"]==="POST"){$question=trim($_POST["question"]);$a=$_POST["a"];$b=$_POST["b"];$c=$_POST["c"];$d=$_POST["d"];$correct=$_POST["correct"];$x=$conn->prepare("UPDATE questions SET question=?,option_a=?,option_b=?,option_c=?,option_d=?,correct_answer=? WHERE id=?");$x->bind_param("ssssssi",$question,$a,$b,$c,$d,$correct,$id);$x->execute();go("manage_questions.php?quiz_id=".$q["quiz_id"]);}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Question</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card panel-card"><div class="card-body p-4"><h2>Edit Question</h2><form method="post"><textarea name="question" class="form-control mb-3"><?=e($q["question"])?></textarea><div class="row g-3"><?php foreach(["a","b","c","d"] as $x):$f="option_".$x;?><div class="col-md-6"><input name="<?=$x?>" value="<?=e($q[$f])?>" class="form-control"></div><?php endforeach;?></div><select name="correct" class="form-select my-3"><?php foreach(["A","B","C","D"] as $x):?><option <?=$q["correct_answer"]===$x?"selected":""?>><?=$x?></option><?php endforeach;?></select><button class="btn btn-primary">Update Question</button></form></div></div></div></body></html>
